insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-192', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Although oxygen has a higher nuclear charge than nitrogen, its first ionisation enthalpy is lower because', '["oxygen has the larger atomic radius","the extra electron in 2p⁴ is paired and is easier to remove","nitrogen has a filled 2p⁶ shell","oxygen lacks a 2s subshell"]'::jsonb, 1, 'Size would suggest IE(O) > IE(N), but pairing repulsion in 2p⁴ reverses the trend.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'ionization-enthalpy') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
