insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-195', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Electron gain enthalpy is the enthalpy change when an electron is added to a neutral gaseous atom to form a', '["cation","uninegative ion","crystal lattice","hydrated proton"]'::jsonb, 1, 'The defining process is X(g) + e⁻ → X⁻(g); ΔegH is usually negative when energy is released.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'electron-gain') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
