insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-197', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Halogens have the most negative electron gain enthalpies in their respective periods because they', '["have empty valence shells","are one electron short of a noble-gas configuration","are the largest atoms of the period","cannot form anions"]'::jsonb, 1, 'Adding one electron completes ns² np⁶ and releases a large amount of energy.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'electron-gain') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
